import json,pathlib
for p in sorted(pathlib.Path.home().joinpath('.codex/sessions').rglob('rollout-*.jsonl')):
 print('\nSESSION',p.name)
 msgs=[]
 for line in p.open():
  try: o=json.loads(line)
  except ValueError: continue
  v=o.get('payload',{})
  if o.get('type')=='response_item' and v.get('type')=='message' and v.get('role') in ('user','assistant'):
   t='\n'.join(c.get('text','') for c in v.get('content',[]) if c.get('type') in ('input_text','output_text'))
   if v.get('role')=='user' and (t.startswith('# AGENTS.md') or t.startswith('<environment_context>')): continue
   if v.get('role')=='user' or v.get('phase')=='final': msgs.append((v.get('role'),t))
 for role,t in msgs:
  print(role.upper(),t[:4500])
