import json,glob,os
for f in sorted(glob.glob(os.path.expanduser('~/.codex/sessions/**/*.jsonl'),recursive=True)):
 print('\n',os.path.basename(f)[8:27])
 for l in open(f):
  try: o=json.loads(l); p=o.get('payload',{}); role=p.get('role'); c=p.get('content',[])
  except: continue
  if o.get('type')=='response_item' and role in ('user','assistant') and (role=='user' or p.get('phase')=='final_answer'):
   s=' '.join(x.get('text','') for x in c if isinstance(x,dict));
   if s and not s.startswith(('# AGENTS.md','<environment_context>','<INSTRUCTIONS>')): print(role, s[:900].replace('\n',' '))
